<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Illuminate\Support\Facades\DB; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Requests\AssignmentRequest; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Assignment; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Policy; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\AssignmentMatchCounter; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\AuditService;
class AssignmentController extends Controller { public function index(){return view('iapm::assignments.index',['assignments'=>Assignment::with(['policy','deviceGroups'])->orderByDesc('priority')->paginate(50)]);}
    public function preview(AssignmentRequest $request,AssignmentMatchCounter $counter){$data=$request->validated();$data['device_group_ids']=$request->input('device_group_ids',[]);return response()->json($counter->count($data));}
    private function formData(Assignment $assignment):array{return ['assignment'=>$assignment,'policies'=>Policy::orderBy('name')->get(),'deviceGroups'=>\App\Models\DeviceGroup::orderBy('name')->get(['id','name']),'locations'=>\App\Models\Location::orderBy('location')->get(['id','location'])];} public function create(){return view('iapm::assignments.form',$this->formData(new Assignment));} public function store(AssignmentRequest $r,AuditService $audit){$a=DB::transaction(function()use($r){$d=$r->safe()->except(['device_group_ids','receivers']);$d['metadata_json']=['receivers'=>$r->input('receivers',[])];$a=Assignment::create($d);foreach($r->input('device_group_ids',[]) as $id)$a->deviceGroups()->create(['device_group_id'=>$id,'inclusion_mode'=>$r->input('match_mode')==='exclude'?'exclude':'include']);return $a;});$audit->record($r,'created','assignment',$a,null,$a->toArray());return redirect()->route('iapm.assignments.index')->with('status','Assignment created.');} public function edit(Assignment $assignment){$assignment->load('deviceGroups');return view('iapm::assignments.form',$this->formData($assignment));} public function update(AssignmentRequest $r,Assignment $assignment,AuditService $audit){$before=$assignment->toArray();DB::transaction(function()use($r,$assignment){$d=$r->safe()->except(['device_group_ids','receivers']);$d['metadata_json']=['receivers'=>$r->input('receivers',[])];$assignment->update($d);$assignment->deviceGroups()->delete();foreach($r->input('device_group_ids',[]) as $id)$assignment->deviceGroups()->create(['device_group_id'=>$id,'inclusion_mode'=>$r->input('match_mode')==='exclude'?'exclude':'include']);});$audit->record($r,'updated','assignment',$assignment,$before,$assignment->fresh()->toArray());return back()->with('status','Assignment updated.');} public function destroy(Request $r,Assignment $assignment,AuditService $audit){abort_unless($r->user()->can('manage iapm assignments'),403);$before=$assignment->toArray();$assignment->delete();$audit->record($r,'deleted','assignment',$assignment->id,$before,null);return redirect()->route('iapm.assignments.index');} }
